using System;
using System.IO;
using System.Linq;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;

// Main.unity is generated by MainSceneBuilder, so it goes stale when the builder or the models change.
// Pressing Play in a stale Main scene asks whether to rebuild it first.
[InitializeOnLoad]
static class StaleSceneGuard
{
    const string ScenePath = "Assets/_Project/Scenes/Main.unity";

    static StaleSceneGuard() => EditorApplication.playModeStateChanged += OnPlayModeChanged;

    static void OnPlayModeChanged(PlayModeStateChange change)
    {
        if (change != PlayModeStateChange.ExitingEditMode || Application.isBatchMode)
            return;
        if (EditorSceneManager.GetActiveScene().path != ScenePath || !IsStale(out string newest))
            return;

        int choice = EditorUtility.DisplayDialogComplex(
            "Main scene is out of date",
            $"{Path.GetFileName(newest)} changed after Main.unity was last built, so the scene may be missing the latest changes.",
            "Rebuild and play", "Play anyway", "Cancel");
        if (choice == 1)
            return;
        EditorApplication.isPlaying = false;
        if (choice == 0)
            EditorApplication.delayCall += () =>
            {
                MainSceneBuilder.BuildFromCommandLine();
                EditorApplication.isPlaying = true;
            };
    }

    static bool IsStale(out string newest)
    {
        DateTime scene = File.GetLastWriteTimeUtc(ScenePath);
        var sources = Directory.GetFiles("Assets/_Project/Art/Models", "*.fbx", SearchOption.AllDirectories)
            .Concat(Directory.GetFiles("Assets/_Project/Audio", "*.wav", SearchOption.AllDirectories))
            .Append("Assets/_Project/Scripts/Editor/MainSceneBuilder.cs");
        newest = sources.OrderByDescending(File.GetLastWriteTimeUtc).First();
        return File.GetLastWriteTimeUtc(newest) > scene;
    }
}
